// Small chat app. Keeps the conversation in messages.json and prints it.
import { readFileSync } from "node:fs";

const messages = JSON.parse(readFileSync(new URL("./messages.json", import.meta.url)));
for (const m of messages) console.log(`${m.from}: ${m.text}`);

// Reads the last chat message aloud with ElevenLabs.
import { ElevenLabsClient } from "@elevenlabs/elevenlabs-js";

const client = new ElevenLabsClient();
await client.textToSpeech.convert("JBFqnCBsd6RMkjVDRZzb", { text: "Lunch at noon?" });

